// Fast, side-effect-free freshness check for the committed generated files.
//
// Why this exists: editing owner-login-app.js (or the Sales engines, or any page
// asset) shifts line numbers and hashes that are baked into generated docs. CI
// catches the resulting staleness, but only ~18 minutes into the browser shards
// (generated-determinism-ext20, write-path-inventory, modules-ext15). This runs the
// SAME generator commands CI's specs check against, in a couple of seconds, so a
// contributor sees "stale" immediately after a source edit instead of in CI.
//
//   node tests/tools/check-generated.js          → PASS/STALE report; exit 1 if stale
//   node tests/tools/check-generated.js --write   → regenerate in place (same as
//                                                   running each generator by hand)
//
// It reuses the existing generators unchanged:
//   module-map.js --write | write-paths.js --md --json --inventory-md
//   refresh-asset-versions.js | sales-inventory.js --write
// In check mode it snapshots each output's current bytes, runs the generators,
// compares, then restores the snapshot — so pre-existing uncommitted edits are kept
// and the working tree is left exactly as it was. It writes nothing of its own.
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const ROOT = path.join(__dirname, '..', '..');
const OPS = path.join(ROOT, 'docs', 'ops');

// The generators and the files each one owns. Keep this in step with the tools.
const GENERATORS = [
  { cmd: ['tests/tools/module-map.js', '--write'],
    outputs: ['docs/ops/APPLICATION_MODULE_MAP_EXT15.md'] },
  { cmd: ['tests/tools/write-paths.js', '--md', '--json', '--inventory-md'],
    outputs: ['docs/ops/WRITE_PATH_MATRIX.md', 'docs/ops/WRITE_PATH_INVENTORY.md', 'docs/ops/MUTATION_WRITE_PATH_INVENTORY.json'] },
  { cmd: ['tests/tools/refresh-asset-versions.js'],
    outputs: ['owner-login.html', 'change-password.html', 'search.html', 'dashboard.html', 'index.html', 'manual-order-entry.html'] },
  { cmd: ['tests/tools/sales-inventory.js', '--write'],
    outputs: ['docs/ops/SALES_INVENTORY.md'] },
];

const allOutputs = [...new Set(GENERATORS.flatMap(g => g.outputs))];
const write = process.argv.includes('--write');
const read = p => { try { return fs.readFileSync(path.join(ROOT, p)); } catch { return null; } };

// Snapshot before (skipped in --write mode, where we keep the regenerated bytes).
const before = write ? null : Object.fromEntries(allOutputs.map(p => [p, read(p)]));

for (const g of GENERATORS) {
  try {
    execFileSync(process.execPath, g.cmd, { cwd: ROOT, stdio: 'pipe' });
  } catch (e) {
    console.error('generator failed:', g.cmd.join(' '), '\n', (e.stderr || e.stdout || e.message).toString());
    process.exit(2);
  }
}

if (write) {
  console.log('regenerated:', allOutputs.join(', '));
  process.exit(0);
}

// Compare, then restore the snapshot so nothing is left changed on disk.
const stale = [];
for (const p of allOutputs) {
  const now = read(p);
  const was = before[p];
  const same = (was === null && now === null) || (was !== null && now !== null && was.equals(now));
  if (!same) stale.push(p);
  if (was !== null && (now === null || !was.equals(now))) fs.writeFileSync(path.join(ROOT, p), was);
  else if (was === null && now !== null) { try { fs.unlinkSync(path.join(ROOT, p)); } catch {} }
}

if (stale.length) {
  console.error('STALE generated files (regenerate with `node tests/tools/check-generated.js --write`):');
  stale.forEach(p => console.error('  - ' + p));
  console.error('\nThese are exactly what CI\'s generated-determinism-ext20 / write-path-inventory /');
  console.error('modules-ext15 / sales-inventory specs check. Working tree left unchanged.');
  process.exit(1);
}
console.log('generated files are fresh (' + allOutputs.length + ' checked):', allOutputs.join(', '));
